<script setup>
import { computed } from 'vue';
import { Head, Link, useForm } from '@inertiajs/vue3';
import AppLayout from '../../../Layouts/AppLayout.vue';
import DateTimePicker from '../../../Components/Shared/DateTimePicker.vue';
import FormField from '../../../Components/Shared/FormField.vue';
import RupiahInput from '../../../Components/Shared/RupiahInput.vue';
defineOptions({ layout: AppLayout });
const props = defineProps({ store: Object, period: Object, products: Array, methods: Object, submitUrl: String, backUrl: String, settingsUrl: String, catalogUrl: String });
const form = useForm({ delivery_fee_mode: props.period?.delivery_fee_mode ?? props.methods.delivery_fee_mode ?? 'road_distance', delivery_fixed_fee: props.period?.delivery_fixed_fee ?? props.methods.delivery_fixed_fee ?? 0, delivery_rate_per_km: props.period?.delivery_rate_per_km ?? props.methods.delivery_rate_per_km ?? 0, priority_enabled: props.period?.priority_enabled ?? props.methods.delivery_options?.priority?.enabled ?? false, priority_fee: props.period?.priority_fee ?? props.methods.delivery_options?.priority?.fee ?? 0, priority_minutes: props.period?.priority_minutes ?? props.methods.delivery_options?.priority?.minutes ?? 30, hemat_enabled: props.period?.hemat_enabled ?? props.methods.delivery_options?.hemat?.enabled ?? false, hemat_fee: props.period?.hemat_fee ?? props.methods.delivery_options?.hemat?.fee ?? 0, hemat_minutes: props.period?.hemat_minutes ?? props.methods.delivery_options?.hemat?.minutes ?? 60, delivery_starts_at: props.period?.delivery_starts_at ?? '', delivery_ends_at: props.period?.delivery_ends_at ?? '', name: props.period?.name ?? '', opens_at: props.period?.opens_at ?? '', closes_at: props.period?.closes_at ?? '', pickup_enabled: props.period?.pickup_enabled ?? props.methods.pickup_enabled, delivery_enabled: props.period?.delivery_enabled ?? props.methods.delivery_enabled, items: (props.period?.items ?? []).map(item => ({ ...item })), intent: 'draft' });
const missingProducts = computed(() => form.items.filter(item => !props.products.some(product => product.id === item.catalog_product_id)));
const selected = (id) => form.items.find(item => item.catalog_product_id === id);
const toggle = (product) => { const index = form.items.findIndex(item => item.catalog_product_id === product.id); if (index < 0) form.items.push({ catalog_product_id: product.id, price: product.price, quota: null }); else form.items.splice(index, 1); };
const submit = (event) => { form.intent = event.submitter?.value ?? 'draft'; return props.period ? form.patch(props.submitUrl) : form.post(props.submitUrl); };
</script>
<template>
    <Head :title="period ? 'Edit open order' : 'New open order'" />
    <div class="mx-auto max-w-4xl"><Link :href="backUrl" class="text-sm text-stone-500 hover:underline">← Open orders</Link><p class="mt-6 text-xs text-stone-500">{{ store.name }}</p><h1 class="mt-2 text-3xl font-semibold">{{ period ? 'Edit draft session' : 'New open-order session' }}</h1>
        <form class="mt-7 space-y-6" @submit.prevent="submit">
            <section class="space-y-5 rounded-3xl border border-stone-200 bg-[#fffdf9] p-6 sm:p-8"><FormField v-model="form.name" name="session-name" label="Session name" placeholder="e.g. Weekend coffee" required maxlength="120" :error="form.errors.name" /><div class="grid gap-5 sm:grid-cols-2"><DateTimePicker v-model="form.opens_at" name="po-opens" label="Opens · WIB" :error="form.errors.opens_at" /><DateTimePicker v-model="form.closes_at" name="po-closes" label="Closes · WIB" :error="form.errors.closes_at" /></div><p class="text-xs leading-6 text-stone-500">Use the date and time picker. Sessions with a future start are scheduled automatically. One open or scheduled session is allowed per store.</p></section>
            <section class="rounded-3xl border border-stone-200 bg-[#fffdf9] p-6 sm:p-8"><div class="flex items-center justify-between gap-3"><h2 class="text-xl font-semibold">Products</h2><span class="text-sm text-stone-500">{{ form.items.length }} selected</span></div><p v-if="!products.length" class="mt-4 text-sm text-stone-500">Add products in <Link :href="catalogUrl" class="underline">Catalog</Link> first.</p>
                <div v-for="item in missingProducts" :key="`missing-${item.catalog_product_id}`" class="mt-4 flex items-center justify-between gap-3 rounded-xl bg-amber-50 p-4 text-sm text-amber-900"><span>A selected product is no longer in your catalog.</span><button type="button" class="underline" @click="form.items = form.items.filter(row => row.catalog_product_id !== item.catalog_product_id)">Remove</button></div>
                <div v-for="product in products" :key="product.id" class="mt-4 rounded-2xl border border-stone-200 p-4"><label class="flex items-center gap-3 text-sm font-medium"><input type="checkbox" :checked="Boolean(selected(product.id))" class="size-4 accent-stone-700" @change="toggle(product)">{{ product.name }}<span class="text-xs font-normal text-stone-400">{{ product.category }}</span></label><div v-if="selected(product.id)" class="mt-4 grid gap-5 sm:grid-cols-2"><RupiahInput v-model="selected(product.id).price" :name="`price-${product.id}`" label="Session selling price" required /><div><label class="flex items-center gap-2 text-sm"><input type="checkbox" :checked="selected(product.id).quota === null" class="size-4 accent-stone-700" @change="selected(product.id).quota = $event.target.checked ? null : 1">No quota limit</label><div v-if="selected(product.id).quota !== null" class="mt-3"><label :for="`quota-${product.id}`" class="text-xs font-medium">Session quota</label><input :id="`quota-${product.id}`" v-model="selected(product.id).quota" type="number" min="1" max="1000000" step="1" required class="mt-2 w-full rounded-xl border border-stone-300 px-4 py-3"></div></div></div></div>
            </section>
            <section class="rounded-3xl border border-stone-200 bg-[#fffdf9] p-6 sm:p-8"><h2 class="text-xl font-semibold">Receiving methods</h2><div class="mt-5 flex flex-wrap gap-6"><label class="flex items-center gap-2 text-sm"><input v-model="form.pickup_enabled" type="checkbox" :disabled="!methods.pickup_enabled" class="size-4 accent-stone-700">Pickup</label><label class="flex items-center gap-2 text-sm"><input v-model="form.delivery_enabled" type="checkbox" :disabled="!methods.delivery_enabled" class="size-4 accent-stone-700">Delivery</label></div><p class="mt-3 text-xs leading-6 text-stone-500">Enabled methods, store location and delivery rates are copied from <Link :href="settingsUrl" class="underline">Store settings</Link> when you save. Later settings changes do not update this session.</p></section>
            <section v-if="form.delivery_enabled" class="space-y-5 rounded-3xl border border-stone-200 bg-[#fffdf9] p-6 sm:p-8"><h2 class="text-xl font-semibold">Standard delivery schedule</h2><p class="text-sm text-stone-500">Delivery prices start from Store settings. Changes here apply only to this session.</p><label class="block text-sm">Standard pricing<select v-model="form.delivery_fee_mode" class="mt-2 w-full rounded-xl border border-stone-300 px-4 py-3"><option value="road_distance">Per kilometer</option><option value="fixed">Fixed delivery fee</option></select></label><RupiahInput v-if="form.delivery_fee_mode === 'fixed'" v-model="form.delivery_fixed_fee" name="session-fixed-fee" label="Standard delivery fee" required/><RupiahInput v-else v-model="form.delivery_rate_per_km" name="session-rate" label="Standard fee per kilometer" required/><p class="text-sm text-stone-500">Customers will see this delivery window before checkout. Delivery starts after ordering closes.</p><div class="grid gap-5 sm:grid-cols-2"><DateTimePicker v-model="form.delivery_starts_at" name="delivery-starts" label="Delivery starts · WIB" :error="form.errors.delivery_starts_at"/><DateTimePicker v-model="form.delivery_ends_at" name="delivery-ends" label="Estimated delivery ends · WIB" :error="form.errors.delivery_ends_at"/></div><div class="space-y-4 border-t border-stone-200 pt-5"><h3 class="font-semibold">Optional delivery choices</h3><div v-for="service in ['priority', 'hemat']" :key="service" class="rounded-2xl border border-stone-200 p-4"><label class="flex items-center gap-3 font-medium"><input v-model="form[`${service}_enabled`]" type="checkbox" class="accent-stone-700">{{ service === 'priority' ? 'Priority · Deliver as soon as prepared' : 'Hemat · Starts 15 minutes after PO closes' }}</label><div v-if="form[`${service}_enabled`]" class="mt-4 grid gap-4 sm:grid-cols-2"><RupiahInput v-model="form[`${service}_fee`]" :name="`${service}-fee`" :label="service === 'priority' ? 'Extra fee on top of delivery' : 'Hemat delivery fee'" required/><label class="text-sm">{{ service === 'priority' ? 'Estimated time from ordering (minutes)' : 'Estimated delivery duration (minutes)' }}<input v-model="form[`${service}_minutes`]" type="number" min="1" max="1440" required class="mt-2 w-full rounded-xl border border-stone-300 px-4 py-3"></label></div></div></div></section>
            <div v-if="Object.keys(form.errors).length" role="alert" class="rounded-xl border border-red-200 bg-red-50 p-4 text-sm text-red-700"><p v-for="(message, field) in form.errors" :key="field">{{ message }}</p></div>
            <p class="text-xs leading-6 text-stone-500">Opening publishes your scheduled menu. Customers can order during the session; confirmed orders reduce the session quota. Published sessions cannot be edited in this stage; close or cancel one before creating a replacement.</p>
            <div class="flex flex-wrap gap-3"><button type="submit" value="draft" :disabled="form.processing" class="rounded-xl border border-stone-300 bg-white px-5 py-3 text-sm font-medium disabled:opacity-50">Save draft</button><button type="submit" value="publish" :disabled="form.processing" class="rounded-xl bg-[#504941] px-5 py-3 text-sm font-medium text-white disabled:opacity-50">{{ form.processing ? 'Saving…' : 'Open / schedule session' }}</button></div>
        </form>
    </div>
</template>
